$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;Set-Location $root;function Humanize([string]$n){$t=$n -replace '^Crud','' -replace 'DTO$','' -replace 'Interface$','';$t=[regex]::Replace($t,'(?<=[a-z0-9])(?=[A-Z])',' ');$t=[regex]::Replace($t,'(?<=[A-Z])(?=[A-Z][a-z])',' ');return $t.ToLowerInvariant()};function CDesc([string]$s,[string]$k){$x=Humanize $s;if($k -eq 'interface' -or $s.EndsWith('Interface')){return "Defines the contract for $x within the Cruding component."};if($s.EndsWith('DTO')){return "Carries $x data across Cruding processing boundaries."};if($s.EndsWith('Controller')){return "Handles $x HTTP requests at the Cruding controller boundary."};if($s.EndsWith('Command')){return "Exposes the $x workflow through the Symfony console."};if($s.EndsWith('Resolver')){return "Resolves $x for Cruding request processing."};if($s.EndsWith('Builder')){return "Builds $x values used by Cruding workflows."};if($s.EndsWith('Factory')){return "Creates $x values used by Cruding workflows."};if($s.EndsWith('Guard')){return "Enforces $x rules at the Cruding runtime boundary."};if($s.EndsWith('Handler')){return "Handles $x processing for Cruding operations."};if($s.EndsWith('Provider')){return "Provides $x data to Cruding consumers."};if($s.EndsWith('Reader')){return "Reads $x data required by Cruding."};if($s.EndsWith('Matcher')){return "Matches $x against the active Cruding request."};if($s.EndsWith('Loader')){return "Loads $x configuration or runtime data."};return "Provides the $x responsibility within the Cruding component."};function MDesc([string]$n){if($n -eq '__invoke'){return 'Handles the invokable HTTP or application entrypoint.'};if($n -eq 'supports'){return 'Indicates whether this implementation supports the supplied context.'};if($n -match '^(is|has|can)(.+)$'){return "Indicates whether $(Humanize $Matches[2])."};if($n -match '^(get|find|read|load|resolve|provide|build|create|match|normalize|apply|assert|dump|export|parse|format|bind|dispatch)(.+)$'){$v=@{get='Returns';find='Finds';read='Reads';load='Loads';resolve='Resolves';provide='Provides';build='Builds';create='Creates';match='Matches';normalize='Normalizes';apply='Applies';assert='Asserts';dump='Dumps';export='Exports';parse='Parses';format='Formats';bind='Binds';dispatch='Dispatches'};return "$($v[$Matches[1]]) $(Humanize $Matches[2])."};if($n -eq 'run'){return 'Runs the selected Cruding workflow.'};if($n -eq 'tryRun'){return 'Attempts to run the selected Cruding workflow without forcing a result.'};if($n -eq 'handle'){return 'Handles the operation represented by this service.'};if($n -eq 'execute'){return 'Executes the operation represented by this service.'};return "Executes the $(Humanize $n) operation."};Get-ChildItem src -Recurse -File -Filter '*.php'|ForEach-Object{$p=$_.FullName;$l=[System.Collections.Generic.List[string]](Get-Content $p);$ins=@();for($i=0;$i -lt $l.Count;$i++){$q=$l[$i];if($q -match '^\s*(?:final\s+|abstract\s+|readonly\s+|final\s+readonly\s+|abstract\s+readonly\s+)*(class|interface|trait|enum)\s+([A-Za-z_][A-Za-z0-9_]*)'){$k=$Matches[1];$s=$Matches[2];$j=$i-1;while($j -ge 0 -and ($l[$j].Trim() -eq '' -or $l[$j].Trim().StartsWith('#['))){$j--};if($j -lt 0 -or -not $l[$j].Trim().EndsWith('*/')){$ins+=[pscustomobject]@{I=$i;T=@('/**',' * '+(CDesc $s $k),' */')}}};if($q -match '^(\s*)public\s+(?:static\s+)?function\s+([A-Za-z_][A-Za-z0-9_]*)\s*\('){$d=$Matches[1];$n=$Matches[2];if($n -ne '__construct'){$j=$i-1;while($j -ge 0 -and ($l[$j].Trim() -eq '' -or $l[$j].Trim().StartsWith('#['))){$j--};if($j -lt 0 -or -not $l[$j].Trim().EndsWith('*/')){$ins+=[pscustomobject]@{I=$i;T=@($d+'/**',$d+' * '+(MDesc $n),$d+' */')}}}}};foreach($e in ($ins|Sort-Object I -Descending)){for($k=$e.T.Count-1;$k -ge 0;$k--){$l.Insert($e.I,$e.T[$k])}};if($ins.Count -gt 0){[IO.File]::WriteAllLines($p,$l,(New-Object Text.UTF8Encoding($false)))}};Write-Host 'Applied missing Cruding PHPDoc descriptions.'
